void sort(struct student *students, int n){
    int i, j;
    for(i = 0; i < n-1; i++){
        for(j = 0; j < n-1-i; j++){
            if(students[j].score > students[j+1].score){
                struct student temp = students[j];
                students[j] = students[j+1];
                students[j+1] = temp;
            }
        }
    }
}

